import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_reduce_TriageGen0Test {





    @Test
    public void testReduce_WithNegativeNumerator() {
        // Math.abs(-10) = 10, gcd(10, 20) = 10
        Fraction fraction = Fraction.getFraction(-10, 20);
        Fraction reduced = fraction.reduce();

        assertEquals(-1, reduced.getNumerator());
        assertEquals(2, reduced.getDenominator());
    }






}

